1	// fix_necessity.go は、修正の必要度 (findings[].fix_necessity と fix_necessity_reason)・
2	// 必要度の下限 (runs[].min_fix_necessity)・判定「下限未満」(verdict: below_minimum)・
3	// 下限未満の指摘の参照 (findings[].below_minimum_ref) の検査と、生成サマリへの描画を持つ。
4	// 判定の条件の SSOT は skills/review-triage/references/judgment-flow.md の D9〜D12・E3、
5	// キーの意味の SSOT は同じディレクトリの record-schema.md。
6	package main
7	
8	import (
9		"fmt"
10		"strings"
11	)
12	
13	// recordFixNecessityReason は findings[].fix_necessity_reason を表し、E3 の 2 つの条件の
14	// 結果を持つ。goal_without_action は条件 1 (困る人は、何もしなくても目的を達成できるか)、
15	// workaround は条件 2 (困る人が気づいて取れる回避策があるか) の結果で、条件 1 が not-holds の
16	// ときだけ書く。必要度 (fix_necessity) はこの結果から決まる (fixNecessityFromReason)。
17	// 判定理由の文に書く形にしないのは、書き忘れを検査で見つけられないため (prior_defect と同じ)。
18	type recordFixNecessityReason struct {
19		GoalWithoutAction string `yaml:"goal_without_action"`
20		Workaround        string `yaml:"workaround"`
21		WorkaroundReason  string `yaml:"workaround_reason"`
22	}
23	
24	// recordBelowMinimumRef は findings[].below_minimum_ref を表す。D9 の (1) (前の回までの
25	// 下限未満の指摘と問題が同じ) が成り立った指摘に書く。run と finding は参照先 (1 始まりの
26	// 回番号と、その回の指摘の id)、line_check は D9 の (2) (対象の行が変わっていない) の結果。
27	type recordBelowMinimumRef struct {
28		Run        int    `yaml:"run"`
29		Finding    int    `yaml:"finding"`
30		LineCheck  string `yaml:"line_check"`
31		LineReason string `yaml:"line_reason"`
32	}
33	
34	// fixNecessityRank は必要度の高さを返す (must が最も高い)。列挙に無い値は 0。
35	func fixNecessityRank(v string) int {
36		switch v {
37		case "must":
38			return 3
39		case "should":
40			return 2
41		case "could":
42			return 1
43		}
44		return 0
45	}
46	
47	// fixNecessityJa は必要度を生成サマリに出す表記にする。
48	func fixNecessityJa(v string) string {
49		switch v {
50		case "must":
51			return "Must"
52		case "should":
53			return "Should"
54		case "could":
55			return "Could"
56		}
57		return recordCell(v)
58	}
59	
60	// fixNecessityBelow は、必要度が下限に満たないかを返す。下限が無ければ満たないことは無い。
61	// どちらかが列挙に無い値のときは、比べられないので偽を返す (列挙の誤りは別に報告する)。
62	func fixNecessityBelow(necessity, minimum string) bool {
63		n, m := fixNecessityRank(necessity), fixNecessityRank(minimum)
64		return n > 0 && m > 0 && n < m
65	}
66	
67	// fixNecessityFromReason は、2 つの条件の結果から決まる必要度を返す。どちらかの条件が
68	// undecided なら空 (必要度を付けない)。ok が偽なら、結果の形が誤っていて決まらない。
69	func fixNecessityFromReason(r *recordFixNecessityReason) (necessity string, ok bool) {
70		switch r.GoalWithoutAction {
71		case "holds":
72			return "could", r.Workaround == ""
73		case "undecided":
74			return "", r.Workaround == ""
75		case "not-holds":
76			switch r.Workaround {
77			case "holds":
78				return "should", true
79			case "not-holds":
80				return "must", true
81			case "undecided":
82				return "", true
83			}
84		}
85		return "", false
86	}
87	
88	// judgmentOmitted は、D9 で当たって判定を省略した指摘 (A3・B2) かを返す。
89	func judgmentOmitted(fd recordFinding) bool {
90		return fd.BelowMinimumRef != nil && fd.BelowMinimumRef.LineCheck == "holds"
91	}
92	
93	// recordFixNecessityFirstRun は、記録の中で最初に fix_necessity_reason か、回の
94	// min_fix_necessity を書いた回の添字を返す。無ければ -1。この回と、それより後の回では
95	// fix_necessity_reason を必須にする。過去の記録を書き換えさせずに通すための決め方で、理由は
96	// recordPriorDefectFirstRun と同じ。回の下限も見るのは、下限を書いた回は必要度を判定する規則で
97	// 判定した回なので、その回で必要度を全件書き忘れた記録を報告するため。
98	func recordFixNecessityFirstRun(runs []recordRun) int {
99		for ri, run := range runs {
100			if run.MinFixNecessity != "" {
101				return ri
102			}
103			for _, fd := range run.Findings {
104				if fd.FixNecessityReason != nil {
105					return ri
106				}
107			}
108		}
109		return -1
110	}
111	
112	// recordFixNecessityProblems は、判定を省略していない指摘 1 件の必要度を検査する。
113	// 書く条件は E3 を行ったかで決まる。判定フローでは、D4 で根拠を確認した指摘
114	// (premise_check.result が verified) だけが E3 に進む。required が偽の回
115	// (recordFixNecessityFirstRun の回より前の回) では、無くても報告しない。
116	// minimum はその回の必要度の下限 (無ければ空)。
117	func recordFixNecessityProblems(required bool, minimum string, fd recordFinding) []string {
118		var problems []string
119		add := func(format string, args ...any) {
120			problems = append(problems, fmt.Sprintf(format, args...))
121		}
122		if fd.FixNecessity != "" && fixNecessityRank(fd.FixNecessity) == 0 {
123			add("fix_necessity は must / should / could のいずれか (決められなければ書かない): %q", fd.FixNecessity)
124		}
125		// 下限未満にできるのは、必要度を決めた指摘だけ。必要度の無い下限未満は、下の対応の
126		// 検査では見つからない (理由の無い指摘と、決められなかった指摘の両方がある) ので、ここで見る。
127		if fd.Verdict == "below_minimum" && fd.FixNecessity == "" {
128			add("verdict が below_minimum なのに fix_necessity がありません (下限未満にできるのは、必要度を決めた指摘だけ)")
129		}
130		verified := fd.PremiseCheck.Result == "verified"
131		r := fd.FixNecessityReason
132		if r == nil {
133			switch {
134			case fd.FixNecessity != "":
135				add("fix_necessity があるのに fix_necessity_reason がありません (必要度は、E3 の 2 つの条件の結果から決める)")
136			case verified && required:
137				add("fix_necessity_reason がありません (D4 で根拠を確認した指摘は E3 で必要度を判定するので、条件の結果を書く。この記録では、この回かそれより前の回で fix_necessity_reason を書いている)")
138			}
139			return problems
140		}
141		if !verified {
142			// E3 に進んでいない指摘の必要度は、どの値でも判定の経路と矛盾するので、中身は検査しない。
143			add("fix_necessity_reason は E3 を行った指摘 (premise_check.result が verified) にだけ書く (result %q)", fd.PremiseCheck.Result)
144			return problems
145		}
146		shapeValid := true
147		switch r.GoalWithoutAction {
148		case "holds", "not-holds", "undecided":
149		default:
150			shapeValid = false
151			add("fix_necessity_reason.goal_without_action は holds / not-holds / undecided のいずれか: %q", r.GoalWithoutAction)
152		}
153		switch {
154		case r.GoalWithoutAction == "not-holds":
155			switch r.Workaround {
156			case "holds", "not-holds", "undecided":
157			case "":
158				shapeValid = false
159				add("fix_necessity_reason.workaround がありません (goal_without_action が not-holds なら条件 2 を判定する)")
160			default:
161				shapeValid = false
162				add("fix_necessity_reason.workaround は holds / not-holds / undecided のいずれか: %q", r.Workaround)
163			}
164			if r.Workaround != "" && r.WorkaroundReason == "" {
165				add("fix_necessity_reason.workaround_reason がありません (回避策の手段か、無い理由か、決められなかった理由)")
166			}
167		case shapeValid:
168			// 条件 1 が成り立つか決められなければ、条件 2 は判定しない。
169			if r.Workaround != "" || r.WorkaroundReason != "" {
170				shapeValid = false
171				add("fix_necessity_reason.workaround と workaround_reason は、goal_without_action が not-holds のときだけ書く (goal_without_action %q)", r.GoalWithoutAction)
172			}
173		}
174		if !shapeValid {
175			return problems
176		}
177		want, _ := fixNecessityFromReason(r)
178		if fd.FixNecessity != want {
179			if want == "" {
180				add("fix_necessity_reason では必要度が決まらない (undecided がある) のに、fix_necessity %q があります", fd.FixNecessity)
181			} else {
182				add("fix_necessity は、fix_necessity_reason から決まる %s と違います: %q", want, fd.FixNecessity)
183			}
184			return problems
185		}
186		switch {
187		case want == "" && fd.Verdict == "adopted":
188			add("必要度を決められなかった (fix_necessity_reason に undecided がある) のに、verdict が adopted です (決められなければ H8 の保留)")
189		case fd.Verdict == "adopted" && fixNecessityBelow(want, minimum):
190			add("必要度 %s が回の下限 %s に満たないのに、verdict が adopted です (下限に満たなければ B1 の下限未満)", want, minimum)
191		case fd.Verdict == "below_minimum" && want != "" && !fixNecessityBelow(want, minimum):
192			if minimum == "" {
193				add("回に下限 (min_fix_necessity) が無いのに、verdict が below_minimum です")
194			} else {
195				add("必要度 %s が回の下限 %s 以上なのに、verdict が below_minimum です", want, minimum)
196			}
197		}
198		return problems
199	}
200	
201	// belowMinimumRefTarget は below_minimum_ref の参照先の指摘を返す。参照先にできるのは、
202	// この回 (添字 ri) より前の回の、必要度を判定して下限未満にした指摘 (B1) だけ。
203	// 判定を省略した指摘 (B2) は必要度を持たないので、参照先にしない。
204	func belowMinimumRefTarget(doc *recordDoc, ri int, ref *recordBelowMinimumRef) (*recordFinding, string) {
205		if ref.Run < 1 || ref.Run > ri {
206			return nil, fmt.Sprintf("below_minimum_ref の run %d は、この回より前の回ではありません (この回は %d 回目)", ref.Run, ri+1)
207		}
208		findings := doc.Runs[ref.Run-1].Findings
209		for i := range findings {
210			if findings[i].ID != ref.Finding {
211				continue
212			}
213			t := &findings[i]
214			if t.Verdict != "below_minimum" || fixNecessityRank(t.FixNecessity) == 0 {
215				return nil, fmt.Sprintf("below_minimum_ref の参照先 (%d 回目の id %d) は、必要度を判定して下限未満にした指摘ではありません (verdict %q / fix_necessity %q)",
216					ref.Run, ref.Finding, t.Verdict, t.FixNecessity)
217			}
218			return t, ""
219		}
220		return nil, fmt.Sprintf("below_minimum_ref の finding %d は %d 回目の findings にありません", ref.Finding, ref.Run)
221	}
222	
223	// recordBelowMinimumRefProblems は指摘 1 件の below_minimum_ref と、それに関わるキーを検査する。
224	func recordBelowMinimumRefProblems(doc *recordDoc, ri int, fd recordFinding) []string {
225		var problems []string
226		add := func(format string, args ...any) {
227			problems = append(problems, fmt.Sprintf(format, args...))
228		}
229		ref := fd.BelowMinimumRef
230		if ref == nil {
231			if fd.Origin == "prior_below_minimum" {
232				add("origin が prior_below_minimum なのに below_minimum_ref がありません (足した指摘は、前の回のどの指摘かを書く)")
233			}
234			return problems
235		}
236		target, msg := belowMinimumRefTarget(doc, ri, ref)
237		if msg != "" {
238			add("%s", msg)
239		}
240		switch ref.LineCheck {
241		case "holds", "not-holds", "unverifiable":
242		default:
243			add("below_minimum_ref.line_check は holds / not-holds / unverifiable のいずれか: %q", ref.LineCheck)
244		}
245		if ref.LineReason == "" {
246			add("below_minimum_ref.line_reason がありません (対象の行が変わっていないかの結果の理由)")
247		}
248		if !judgmentOmitted(fd) {
249			return problems
250		}
251		// 判定を省略した指摘 (A3・B2)。分類・被害者・帰結・根拠の検証・ゲート・必要度は書かない。
252		// 書いてあると、参照先の値と、この指摘の値のどちらを読むのかが決まらない。
253		for _, kv := range []struct {
254			key     string
255			written bool
256		}{
257			{"category", fd.Category != ""},
258			{"audience", fd.Audience != ""},
259			{"audience_initial", fd.AudienceInitial != ""},
260			{"consequence", fd.Consequence != recordConsequence{}},
261			{"premise_check", fd.PremiseCheck != recordPremise{}},
262			{"gates_fired", len(fd.GatesFired) > 0},
263			{"prior_defect", fd.PriorDefect != nil},
264			{"fix_necessity", fd.FixNecessity != ""},
265			{"fix_necessity_reason", fd.FixNecessityReason != nil},
266		} {
267			if kv.written {
268				add("判定を省略した指摘 (below_minimum_ref.line_check が holds) では %s を書かない (参照先の指摘のものを読む)", kv.key)
269			}
270		}
271		if target == nil {
272			return problems
273		}
274		// D12: 参照先の必要度が、この回の下限以上なら採択 (A3)、満たなければ下限未満 (B2)。
275		want := "adopted"
276		if fixNecessityBelow(target.FixNecessity, doc.Runs[ri].MinFixNecessity) {
277			want = "below_minimum"
278		}
279		if fd.Verdict != want {
280			minimum := doc.Runs[ri].MinFixNecessity
281			if minimum == "" {
282				minimum = "無し"
283			}
284			add("判定を省略した指摘の verdict は、参照先の必要度 %s と回の下限 %s から %s に決まりますが、%q です",
285				target.FixNecessity, minimum, want, fd.Verdict)
286		}
287		return problems
288	}
289	
290	// recordPriorBelowMinimumProblems は、回 (添字 ri) に足すべき下限未満の指摘が、足されているかを
291	// 検査する。それより前の回の、残っている下限未満の指摘 (必要度を判定して下限未満にした指摘で、
292	// この回より前の回の指摘が参照して、判定し直しても採択にしてもいないもの) のうち、必要度がこの回の
293	// 下限以上のもの (下限が無い回ではすべて) は、この回の指摘として足す (record-schema.md の
294	// 「下限未満の指摘の参照」)。足し忘れると、下限を下げても、その指摘は採択にならず直されないまま残る。
295	// 足したかどうかは、この回の指摘の below_minimum_ref が参照しているかで見る。
296	func recordPriorBelowMinimumProblems(doc *recordDoc, ri int) []string {
297		type key struct{ run, finding int }
298		remaining := map[key]string{} // 残っている下限未満の指摘と、その必要度
299		var order []key
300		for pi := 0; pi < ri; pi++ {
301			for _, fd := range doc.Runs[pi].Findings {
302				if ref := fd.BelowMinimumRef; ref != nil && !(judgmentOmitted(fd) && fd.Verdict == "below_minimum") {
303					// 判定し直したか、採択 (A3) にした。参照先は残っていない。
304					delete(remaining, key{ref.Run, ref.Finding})
305				}
306				if fd.Verdict == "below_minimum" && fixNecessityRank(fd.FixNecessity) > 0 {
307					k := key{pi + 1, fd.ID}
308					remaining[k] = fd.FixNecessity
309					order = append(order, k)
310				}
311			}
312		}
313		referenced := map[key]bool{}
314		for _, fd := range doc.Runs[ri].Findings {
315			if ref := fd.BelowMinimumRef; ref != nil {
316				referenced[key{ref.Run, ref.Finding}] = true
317			}
318		}
319		minimum := doc.Runs[ri].MinFixNecessity
320		var problems []string
321		for _, k := range order {
322			necessity, ok := remaining[k]
323			if !ok || referenced[k] || fixNecessityBelow(necessity, minimum) {
324				continue
325			}
326			// 下限が列挙に無い値のときは、比べられないので報告しない (列挙の誤りは別に報告する)。
327			if minimum != "" && fixNecessityRank(minimum) == 0 {
328				continue
329			}
330			limit := "この回に下限が無い"
331			if minimum != "" {
332				limit = "この回の下限 " + minimum + " 以上"
333			}
334			problems = append(problems, fmt.Sprintf(
335				"残っている下限未満の指摘 (%d 回目の id %d。必要度 %s) が、%sのに、この回の findings に足されていません (origin: prior_below_minimum と below_minimum_ref を書いて足す)",
336				k.run, k.finding, necessity, limit))
337		}
338		return problems
339	}
340	
341	// findingFixNecessity は指摘の必要度を返す。判定を省略した指摘は、参照先の必要度。
342	// 分からなければ空。
343	func findingFixNecessity(doc *recordDoc, ri int, fd recordFinding) string {
344		if !judgmentOmitted(fd) {
345			return fd.FixNecessity
346		}
347		if target, _ := belowMinimumRefTarget(doc, ri, fd.BelowMinimumRef); target != nil {
348			return target.FixNecessity
349		}
350		return ""
351	}
352	
353	// renderFixNecessityCounts は推移の表の必要度の 3 列 (Must・Should・Could) を返す。
354	// 判定に関わらず、その回で必要度が分かる指摘を数える。fix_necessity_reason を必須にする回
355	// (recordFixNecessityFirstRun) より前の回 (必須にする回が無い記録ではすべての回) は「—」にする。0 と書くと、
356	// 必要度を判定して 0 件だったように読めるため。
357	func renderFixNecessityCounts(doc *recordDoc, ri, firstRun int) []string {
358		if firstRun < 0 || ri < firstRun {
359			return []string{"—", "—", "—"}
360		}
361		counts := map[string]int{}
362		for _, fd := range doc.Runs[ri].Findings {
363			counts[findingFixNecessity(doc, ri, fd)]++
364		}
365		return []string{
366			fmt.Sprint(counts["must"]), fmt.Sprint(counts["should"]), fmt.Sprint(counts["could"]),
367		}
368	}
369	
370	// belowMinimumEntry は、節「下限未満の指摘」の 1 行になる指摘 (必要度を判定して下限未満に
371	// した指摘)。resolved は、後の回の指摘が参照して、判定し直したか採択 (A3) にしたこと。
372	// reported は、同じ問題がまた報告されて判定を省略した指摘 (B2) の位置。
373	type belowMinimumEntry struct {
374		run      int
375		finding  recordFinding
376		resolved bool
377		reported []string
378	}
379	
380	// renderBelowMinimumSection は節「下限未満の指摘」を書く。記録に下限未満の指摘が 1 件も
381	// 無ければ何も書かない。並べるのは残っている指摘だけで、必要度ごとの表にする。
382	// 件数はここで数え、人が書いた集計をどこからも読まない (推移の表と同じ)。
383	func renderBelowMinimumSection(b *strings.Builder, doc *recordDoc) {
384		var entries []*belowMinimumEntry
385		index := map[[2]int]*belowMinimumEntry{}
386		hasBelowMinimum := false
387		for ri, run := range doc.Runs {
388			for _, fd := range run.Findings {
389				if fd.Verdict == "below_minimum" {
390					hasBelowMinimum = true
391				}
392				if ref := fd.BelowMinimumRef; ref != nil {
393					if e := index[[2]int{ref.Run, ref.Finding}]; e != nil {
394						if judgmentOmitted(fd) && fd.Verdict == "below_minimum" {
395							e.reported = append(e.reported, fmt.Sprintf("%d 回目 #%d", ri+1, fd.ID))
396						} else {
397							e.resolved = true
398						}
399					}
400				}
401				if fd.Verdict == "below_minimum" && fixNecessityRank(fd.FixNecessity) > 0 {
402					e := &belowMinimumEntry{run: ri + 1, finding: fd}
403					entries = append(entries, e)
404					index[[2]int{ri + 1, fd.ID}] = e
405				}
406			}
407		}
408		if !hasBelowMinimum {
409			return
410		}
411		b.WriteString("\n## 下限未満の指摘\n")
412		remaining := 0
413		for _, necessity := range []string{"must", "should", "could"} {
414			var rows []*belowMinimumEntry
415			for _, e := range entries {
416				if !e.resolved && e.finding.FixNecessity == necessity {
417					rows = append(rows, e)
418				}
419			}
420			if len(rows) == 0 {
421				continue
422			}
423			remaining += len(rows)
424			fmt.Fprintf(b, "\n### %s (%d 件)\n\n", fixNecessityJa(necessity), len(rows))
425			b.WriteString("| 判定した回 | 指摘 | 回避策 | また報告された回 |\n")
426			b.WriteString("| --- | --- | --- | --- |\n")
427			for _, e := range rows {
428				b.WriteString(recordRow(renderBelowMinimumCells(e)))
429			}
430		}
431		if remaining == 0 {
432			b.WriteString("\n残っている下限未満の指摘はありません (後の回で判定し直したか、採択にした)。\n")
433		}
434	}
