436	// renderBelowMinimumCells は節「下限未満の指摘」の 1 行のセルのスライスを返す。
437	func renderBelowMinimumCells(e *belowMinimumEntry) []string {
438		fd := e.finding
439		loc := fd.File
440		if fd.Line > 0 {
441			loc = fmt.Sprintf("%s:%d", fd.File, fd.Line)
442		}
443		// 回避策は、条件 2 を判定した指摘 (Should) だけが持つ。条件 1 が成り立つ指摘 (Could) は
444		// 何もしなくても目的を達成できるので、回避策を書かない。
445		workaround := "—"
446		if r := fd.FixNecessityReason; r != nil && r.WorkaroundReason != "" {
447			workaround = recordCell(r.WorkaroundReason)
448		}
449		reported := "—"
450		if len(e.reported) > 0 {
451			reported = strings.Join(e.reported, "、")
452		}
453		return []string{
454			fmt.Sprintf("%d 回目 #%d", e.run, fd.ID),
455			"`" + recordCell(loc) + "` " + recordCell(fd.Summary),
456			workaround,
457			reported,
458		}
459	}
