461	// renderFixNecessityNote は、判定セルに添える必要度と、下限未満の指摘の参照を返す。
462	// どちらも無い指摘では空。過去の記録の判定セルを変えないため。
463	func renderFixNecessityNote(fd recordFinding) string {
464		var note string
465		if fd.FixNecessityReason != nil {
466			necessity := "決められない"
467			if fd.FixNecessity != "" {
468				necessity = fixNecessityJa(fd.FixNecessity)
469			}
470			note += " (必要度: " + necessity + ")"
471		}
472		if ref := fd.BelowMinimumRef; ref != nil {
473			if judgmentOmitted(fd) {
474				note += fmt.Sprintf(" (%d 回目の #%d と同じ)", ref.Run, ref.Finding)
475			} else {
476				note += fmt.Sprintf(" (%d 回目の #%d と同じ問題を判定し直した)", ref.Run, ref.Finding)
477			}
478		}
479		return note
480	}
