81	const fixNecessityPlanYAML = "      - problem_id: P1\n        cause: 原因\n        finding_ids: [1]\n        approach: 直す\n        sha: abc1234\n        status: done\n"
82	
83	// fixNecessityRecordYAML は、必要度と下限を書いた 3 回の記録。
84	//   - 1 回目 (下限 must): Must の採択・Should と Could の下限未満 (B1)・必要度を決められない
85	//     保留 (H8)・Should の却下 (R3。下限に満たなくても却下のまま)
86	//   - 2 回目 (下限 should): 1 回目の Should を採択 (A3。下限を下げたので足した指摘)・
87	//     1 回目の Could がまた報告されて判定を省略 (B2)
88	//   - 3 回目 (下限なし): 1 回目の Could の行が変わっていたので判定し直して採択
89	func fixNecessityRecordYAML() string {
90		run1 := fixNecessityRunYAML("must",
91			fixNecessityFindingYAML(1, "must", reasonMust, "adopted", "A2")+
92				fixNecessityFindingYAML(2, "should", reasonShould, "below_minimum", "B1")+
93				fixNecessityFindingYAML(3, "could", reasonCould, "below_minimum", "B1")+
94				fixNecessityFindingYAML(4, "", reasonUndecided, "held", "H8")+
95				strings.Replace(fixNecessityFindingYAML(5, "should", reasonShould, "rejected", "R3"),
96					"        verdict: rejected\n", "        gates_fired: [developer-domain]\n        verdict: rejected\n", 1),
97			fixNecessityPlanYAML)
98		run2 := fixNecessityRunYAML("should",
99			omittedFindingYAML(1, 1, 2, "prior_below_minimum", "adopted", "A3")+
100				omittedFindingYAML(2, 1, 3, "", "below_minimum", "B2"),
101			fixNecessityPlanYAML)
102		rejudged := strings.Replace(fixNecessityFindingYAML(1, "could", reasonCould, "adopted", "A2"),
103			"        verdict: adopted\n",
104			"        below_minimum_ref:\n          run: 1\n          finding: 3\n          line_check: not-holds\n          line_reason: 30 行目は 2 回目の修正が書き換えた\n        verdict: adopted\n", 1)
105		run3 := fixNecessityRunYAML("", rejudged, "")
106		return "runs:\n" + run1 + run2 + run3
107	}
